const envelope = $input.first().json;
const analysis = envelope.performance_analysis;
const answers = envelope.owner_context?.interpretation?.answers ?? [];
const normalize = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const changes = [];
for (const answer of answers) {
  if (Number(answer?.confidence ?? 0) < 0.8 || answer?.value === null || answer?.value === undefined) continue;
  const field = String(answer.field ?? '');
  const summaryMatch = field.match(/^summary:(period|base_date|final_points)$/);
  if (summaryMatch) { const key = summaryMatch[1]; const previous = key === 'final_points' ? analysis.summary[key] : analysis[key]; if (key === 'final_points') analysis.summary[key] = Number(answer.value); else analysis[key] = String(answer.value); changes.push({field, previous, value: answer.value, provenance: 'OWNER_PROVIDED'}); continue; }
  const match = field.match(/^indicator:([^:]+):(target|achieved|attainment_percent|projected_final_percent)$/);
  if (!match) continue;
  const indicator = analysis.indicators.find((item) => item.indicator_id === match[1] || normalize(item.name) === normalize(answer.indicator));
  if (!indicator) continue;
  const numeric = Number(answer.value);
  if (!Number.isFinite(numeric)) continue;
  const key = match[2];
  const previous = indicator[key];
  indicator[key] = numeric;
  indicator.owner_provided = {...(indicator.owner_provided ?? {}), [key]: {value: numeric, answer: answer.answer, confidence: answer.confidence, provenance: 'OWNER_PROVIDED'}};
  changes.push({indicator_id: indicator.indicator_id, field: key, previous, value: numeric, provenance: 'OWNER_PROVIDED'});
}
for (const indicator of analysis.indicators) { if (indicator.attainment_percent === null && indicator.target !== null && indicator.achieved !== null && Number(indicator.target) !== 0) indicator.attainment_percent = Math.round((Number(indicator.achieved) / Number(indicator.target)) * 10000) / 100; }
envelope.owner_context_applied = {applied: changes.length > 0, changes, source: 'OWNER_PROVIDED'};
return [{json: {...envelope, performance_analysis: analysis}}];

